# Check `todo-app` integration with external services.
{ inputs, ... }:
{
  perSystem = { self', pkgs, ... }: {
    process-compose.todo-app-integ-test = { config, ... }: {
      imports = [
        inputs.services-flake.processComposeModules.default
        ./services
      ];
      services.postgrest.unixSocket = "./data/pgrst.sock";
      # `test` is a reserved name in `process-compose-flake`.
      # This process is disabled by default and is only enabled when `nix flake check` is run,
      # which is only done in CI.
      settings.processes.test = {
        environment = {
          # If not set, `todo-app` will try to connect to `postgrest` using TCP.
          PGRST_SERVER_UNIX_SOCKET = config.services.postgrest.unixSocket;
        };
        command = pkgs.writeShellApplication {
          name = "todo-app-integration-test";
          runtimeInputs = [ self'.packages.default ];
          # TODO: Capture output and check for expected strings.
          text = ''
            # Function to print a separator
            print_separator() {
              echo "----------------------------------------"
              echo "  $1"
              echo "----------------------------------------"
            }
            print_separator "Test viewing all todos"
            todo-app viewAll

            print_separator "Test viewing pending todos"
            todo-app view

            print_separator "Test adding a todo"
            todo-app add "Buy milk"

            print_separator "Test completing a todo"
            # Workaround for https://www.shellcheck.net/wiki/SC1010
            todo-app "done" 1

            print_separator "Test deleting a todo"
            todo-app delete 1

            print_separator "Test resetting the todo list"
            todo-app reset
          '';
        };
        depends_on."postgrest".condition = "process_healthy";
      };
    };
  };
}

# Custom service (not provided by `services-flake`) configuration for `postgrest`.
# See https://community.flake.parts/services-flake/custom-service
{ pkgs, lib, config, ... }:
let
  inherit (lib) types;
in
{
  options = {
    services.postgrest = {
      enable = lib.mkEnableOption "postgrest";
      unixSocket = lib.mkOption {
        type = types.nullOr types.str;
        default = null;
        description = "The path to the socket to bind to";
        example = "/tmp/pgrst.sock";
      };
      config = lib.mkOption {
        type = types.attrsOf types.str;
        # TODO: use https://github.com/srid/flake-root for `db-uri` and `server-unix-socket`
        default = {
          # Note: socket path in connection uri cannot contain `/`, so we need to URL-encode it.
          # see https://www.postgresql.org/docs/current/libpq-connect.html#LIBPQ-CONNSTRING-KEYWORD-VALUE
          # TODO: re-use `config.services.postgres."pg".dataDir`
          db-uri = "postgres://\${PWD//\//%2F}%2Fdata%2Fpg/todo";
          db-schemas = "api";
          db-anon-role = "todo_user";
        };
      };
    };
  };
  config = lib.mkIf config.services.postgrest.enable {
    settings.processes.postgrest = {
      environment = {
        PGRST_DB_SCHEMAS = config.services.postgrest.config.db-schemas;
        PGRST_DB_ANON_ROLE = config.services.postgrest.config.db-anon-role;
      } // lib.optionalAttrs (config.services.postgrest.unixSocket != null) {
        PGRST_SERVER_UNIX_SOCKET = config.services.postgrest.unixSocket;
      };
      command = pkgs.writeShellApplication {
        name = "pg_rest";
        runtimeInputs = [ pkgs.haskellPackages.postgrest ];
        text =
          ''
            # Can't be set in `settings.processes.postgrest.environment` because the value has to be evaluated in the shell
            PGRST_DB_URI="${config.services.postgrest.config.db-uri}";
            # Have to export explicitly: https://www.shellcheck.net/wiki/SC2155
            export PGRST_DB_URI;
            exec postgrest
          '';
      };
      readiness_probe = {
        # `http://localhost` is to tell curl to use the HTTP protocol and `localhost` is just a dummy hostname
        exec.command = if config.services.postgrest.unixSocket != null then
          "${lib.getExe' pkgs.curl "curl"} --unix-socket ${config.services.postgrest.unixSocket} http://localhost"
        else
          # TODO: configurable hostname and port
          "${lib.getExe pkgs.curl} http://localhost:3000";
      };
    };
  };
}

-- This schema has been taken from https://postgrest.org/en/stable/tutorials/tut0.html
create schema api;
create table if not exists api.todos (
  id serial primary key, done boolean not null default false, 
  task text not null
);
insert into api.todos (task) 
values 
  ('finish tutorial 0'), 
  ('pat self on back');
create role authenticator noinherit login password 'mysecretpassword';
create role todo_user nologin;
grant todo_user to authenticator;
-- Granting all permissions for tutorial purposes only
-- Follow this to use JWT and secure your api calls: https://postgrest.org/en/stable/tutorials/tut1.html
grant all on schema api to todo_user;
grant all on api.todos to todo_user;
grant all on sequence api.todos_id_seq to todo_user;
-- To reset the sequence
create function api.reset_id() returns void language plpgsql as $$ begin alter sequence api.todos_id_seq restart with 1;
end;
$$;
-- This is needed because to change ownership of sequence, the same owner has to own the table
-- TODO: Find a better way to do this 
alter table 
  api.todos owner to todo_user;
alter sequence api.todos_id_seq owner to todo_user;
